export let $currentBlendMode = "normal";
export let $funcCode = 0;
export const $setCurrentBlendMode = (blend_mode) => {
    $currentBlendMode = blend_mode;
};
export const $setFuncCode = (code) => {
    $funcCode = code;
};
export const $getBlendState = (mode) => {
    switch (mode) {
        case "add":
            return {
                "color": {
                    "srcFactor": "one",
                    "dstFactor": "one",
                    "operation": "add"
                },
                "alpha": {
                    "srcFactor": "one",
                    "dstFactor": "one-minus-src-alpha",
                    "operation": "add"
                }
            };
        case "screen":
            return {
                "color": {
                    "srcFactor": "one-minus-dst",
                    "dstFactor": "one",
                    "operation": "add"
                },
                "alpha": {
                    "srcFactor": "one",
                    "dstFactor": "one-minus-src-alpha",
                    "operation": "add"
                }
            };
        case "alpha":
            return {
                "color": {
                    "srcFactor": "zero",
                    "dstFactor": "src-alpha",
                    "operation": "add"
                },
                "alpha": {
                    "srcFactor": "zero",
                    "dstFactor": "src-alpha",
                    "operation": "add"
                }
            };
        case "erase":
            return {
                "color": {
                    "srcFactor": "zero",
                    "dstFactor": "one-minus-src-alpha",
                    "operation": "add"
                },
                "alpha": {
                    "srcFactor": "zero",
                    "dstFactor": "one-minus-src-alpha",
                    "operation": "add"
                }
            };
        case "copy":
            return {
                "color": {
                    "srcFactor": "one",
                    "dstFactor": "zero",
                    "operation": "add"
                },
                "alpha": {
                    "srcFactor": "one",
                    "dstFactor": "zero",
                    "operation": "add"
                }
            };
        // normal and default
        default:
            return {
                "color": {
                    "srcFactor": "one",
                    "dstFactor": "one-minus-src-alpha",
                    "operation": "add"
                },
                "alpha": {
                    "srcFactor": "one",
                    "dstFactor": "one-minus-src-alpha",
                    "operation": "add"
                }
            };
    }
};
